ALTER TABLE phonemes ADD COLUMN audio_us_url VARCHAR(500) NULL AFTER audio_url;
ALTER TABLE phonemes ADD COLUMN audio_gb_url VARCHAR(500) NULL AFTER audio_us_url;

UPDATE phonemes SET audio_us_url = audio_url WHERE audio_url IS NOT NULL AND audio_us_url IS NULL;

UPDATE phonemes SET ipa='/iː/', group_code='VOWEL', category='长元音', sort_order=1, detail_json='{"description":"长元音 /iː/，先观察口型，再跟读例词。","mouth":{"type":"smile","color":"#3154ff"},"pronunciationSteps":["观察嘴唇和下颌位置","保持舌位稳定","先慢读，再连到例词"],"exampleWords":[{"wordId":null,"word":"see","ipa":"/siː/","meaning":"看见","audioUrl":null}],"memoryTip":"用 see 记住 /iː/。","speechFallback":"see"}' WHERE id='p_2';
UPDATE phonemes SET ipa='/ɪ/', group_code='VOWEL', category='短元音', sort_order=2, detail_json='{"description":"短元音 /ɪ/，先观察口型，再跟读例词。","mouth":{"type":"relaxed","color":"#3154ff"},"pronunciationSteps":["观察嘴唇和下颌位置","保持舌位稳定","先慢读，再连到例词"],"exampleWords":[{"wordId":null,"word":"sit","ipa":"/sɪt/","meaning":"坐","audioUrl":null}],"memoryTip":"用 sit 记住 /ɪ/。","speechFallback":"sit"}' WHERE id='p_1';
UPDATE phonemes SET ipa='/p/', group_code='CONSONANT', category='爆破音', sort_order=1, detail_json='{"description":"爆破音 /p/，注意气流和声带状态。","mouth":{"type":"closed","color":"#3154ff"},"pronunciationSteps":["摆好舌位和唇形","感受气流与声带状态","连到例词中练习"],"exampleWords":[{"wordId":null,"word":"pen","ipa":"/pen/","meaning":"钢笔","audioUrl":null}],"memoryTip":"用 pen 记住 /p/。","speechFallback":"pen"}' WHERE id='p_3';


SELECT CONCAT('content_', p.id), 'PHONEME', p.id, '', p.ipa
FROM phonemes p
WHERE NOT EXISTS (
  SELECT 1 FROM content_entries e
  WHERE e.kind = 'PHONEME' AND e.source_id = p.id AND e.scope_id = ''
);

